"""SVG formatting and elementary geometry for the text diagram renderer."""
import math
import struct


def f32(n):
    try:
        return struct.unpack('f', struct.pack('f', n))[0]
    except OverflowError:
        return math.copysign(math.inf, n)


def number(n):
    n = f32(n)
    if math.isnan(n):
        return 'NaN'
    if math.isinf(n):
        return '-inf' if n < 0 else 'inf'
    if n == 0:
        return '-0' if math.copysign(1, n) < 0 else '0'
    if n.is_integer():
        return str(int(n))
    for precision in range(1, 10):
        s = format(n, f'.{precision}g')
        if f32(float(s)) == n:
            break
    if 'e' in s:
        from decimal import Decimal
        s = format(Decimal(s), 'f')
    return s


def escape(s):
    return s.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;').replace('"', '&quot;').replace("'", '&#39;')


STYLE = '''.svgbob line, .svgbob path, .svgbob circle, .svgbob rect, .svgbob polygon {
  stroke: $stroke;
  stroke-width: $width;
  stroke-opacity: 1;
  fill-opacity: 1;
  stroke-linecap: round;
  stroke-linejoin: miter;
}

.svgbob text {
  white-space: pre;
  fill: $stroke;
  font-family: $font;
  font-size: $sizepx;
}

.svgbob rect.backdrop {
  stroke: none;
  fill: $background;
}

.svgbob .broken {
  stroke-dasharray: 8;
}

.svgbob .filled {
  fill: $fill;
}

.svgbob .bg_filled {
  fill: $background;
  stroke-width: 1;
}

.svgbob .nofill {
  fill: $background;
}

'''
for _m in ('arrow', 'diamond', 'circle', 'open_circle', 'big_open_circle'):
    for _end in ('end', 'start'):
        STYLE += '.svgbob .' + _end + '_marked_' + _m + ' {\n  marker-' + _end + ': url(#' + _m + ');\n}\n\n'

DEFS = '''  <defs>
    <marker id="arrow" viewBox="-2 -2 8 8" refX="4" refY="2" markerWidth="7" markerHeight="7" orient="auto-start-reverse">
      <polygon points="0,0 0,4 4,2 0,0"></polygon>
    </marker>
    <marker id="diamond" viewBox="-2 -2 8 8" refX="4" refY="2" markerWidth="7" markerHeight="7" orient="auto-start-reverse">
      <polygon points="0,2 2,0 4,2 2,4 0,2"></polygon>
    </marker>
    <marker id="circle" viewBox="0 0 8 8" refX="4" refY="4" markerWidth="7" markerHeight="7" orient="auto-start-reverse">
      <circle cx="4" cy="4" r="2" class="filled"></circle>
    </marker>
    <marker id="open_circle" viewBox="0 0 8 8" refX="4" refY="4" markerWidth="7" markerHeight="7" orient="auto-start-reverse">
      <circle cx="4" cy="4" r="2" class="bg_filled"></circle>
    </marker>
    <marker id="big_open_circle" viewBox="0 0 8 8" refX="4" refY="4" markerWidth="7" markerHeight="7" orient="auto-start-reverse">
      <circle cx="4" cy="4" r="3" class="bg_filled"></circle>
    </marker>
  </defs>
'''


def document(width, height, elements, options):
    scale = options.get('scale', 1)
    w, h = number(width * scale), number(height * scale)
    from string import Template
    style = Template(STYLE).substitute(
        stroke=options.get('stroke-color', 'black'),
        width=number(options.get('stroke-width', 2)),
        font=options.get('font-family', 'Iosevka Fixed, monospace'),
        sizepx=str(options.get('font-size', 14))+'px',
        background=options.get('background', 'white'),
        fill=options.get('fill-color', 'black'))
    style += options.get('extra-style', '')
    out = f'<svg xmlns="http://www.w3.org/2000/svg" width="{w}" height="{h}" class="svgbob">\n'
    out += '  <style>' + style + '</style>\n' + DEFS
    out += f'  <rect class="backdrop" x="0" y="0" width="{w}" height="{h}"></rect>\n'
    for e in elements:
        out += render(e, scale)
    return out + '</svg>\n'


def line(x1, y1, x2, y2, broken=False, marker=''):
    # All undecorated segments have the same top-to-bottom orientation.
    if (y1, x1) > (y2, x2) and not marker:
        x1, y1, x2, y2 = x2, y2, x1, y1
    return {'type': 'line', 'p': (x1, y1, x2, y2), 'broken': broken, 'marker': marker}


def arc(x1, y1, x2, y2, r, sweep):
    return {'type': 'arc', 'p': (x1, y1, x2, y2), 'r': r, 'sweep': sweep}


def text(x, y, s):
    return {'type': 'text', 'x': x, 'y': y, 'text': s}


def circle(x, y, r, filled=False):
    return {'type': 'circle', 'x': x, 'y': y, 'r': r, 'filled': filled}


def rect(x, y, w, h, rx=0, filled=False, broken=False):
    return {'type': 'rect', 'x': x, 'y': y, 'w': w, 'h': h, 'rx': rx, 'filled': filled, 'broken': broken}


def polygon(points, filled=True):
    return {'type': 'polygon', 'points': points, 'filled': filled}


def render(e, scale=1, indent=2):
    n = lambda x: number(x * scale)
    t = e['type']
    css = lambda s: s + ((' ' + ' '.join(e['classes'])) if e.get('classes') else '')
    if t == 'line':
        x1, y1, x2, y2 = map(n, e['p'])
        cl = 'broken' if e.get('broken') else 'solid'
        if e.get('marker'):
            cl += ' end_marked_' + e['marker']
        result = f'<line x1="{x1}" y1="{y1}" x2="{x2}" y2="{y2}" class="{css(cl)}"></line>'
    elif t == 'arc':
        x1, y1, x2, y2 = map(n, e['p'])
        r = n(e['r'])
        result = f'<path d="M {x1},{y1} A {r},{r} 0,0,{e["sweep"]} {x2},{y2}" class="{css("nofill")}"></path>'
    elif t == 'text':
        result = f'<text x="{n(e["x"])}" y="{n(e["y"])}" >{escape(e["text"])}</text>'
    elif t == 'rect':
        cl = ('broken' if e.get('broken') else 'solid') + (' filled' if e.get('filled') else ' nofill')
        result = f'<rect x="{n(e["x"])}" y="{n(e["y"])}" width="{n(e["w"])}" height="{n(e["h"])}" class="{css(cl)}" rx="{n(e["rx"])}"></rect>'
    elif t == 'circle':
        cl = 'filled' if e.get('filled') else 'nofill'
        result = f'<circle cx="{n(e["x"])}" cy="{n(e["y"])}" r="{n(e["r"])}" class="{css(cl)}"></circle>'
    elif t == 'polygon':
        pts = ' '.join(n(x)+','+n(y) for x, y in e['points'])
        cl = 'filled' if e.get('filled') else 'nofill'
        result = f'<polygon points="{pts}" class="{css(cl)}"></polygon>'
    elif t == 'group':
        opening = '<g' + (f' class="{escape(" ".join(e["classes"]))}"' if e.get('classes') else '') + '>'
        return ' '*indent + opening + '\n' + ''.join(render(item, scale, indent+2) for item in e['items']) + ' '*indent + '</g>\n'
    else:
        raise ValueError(t)
    return ' '*indent + result + '\n'


def translated(e, dx, dy):
    f = dict(e)
    if 'p' in e:
        a,b,c,d = e['p']
        f['p'] = (a+dx,b+dy,c+dx,d+dy)
    if 'x' in e:
        f['x'] += dx
        f['y'] += dy
    if 'points' in e:
        f['points'] = [(a+dx,b+dy) for a,b in e['points']]
    return f


def point_on(p, l):
    x,y = p
    a,b,c,d = l
    return abs((x-a)*(d-b)-(y-b)*(c-a)) < 1e-6 and min(a,c)-1e-6 <= x <= max(a,c)+1e-6 and min(b,d)-1e-6 <= y <= max(b,d)+1e-6


def contacts(a, b):
    if a['type'] not in ('line', 'arc') or b['type'] not in ('line', 'arc'):
        return False
    if a.get('marker') or b.get('marker'):
        return False
    p, q = a['p'], b['p']
    if a['type'] == 'line' and (point_on(q[:2], p) or point_on(q[2:], p)):
        return True
    if b['type'] == 'line' and (point_on(p[:2], q) or point_on(p[2:], q)):
        return True
    return p[:2] in (q[:2], q[2:]) or p[2:] in (q[:2], q[2:])


def merge(a, b):
    ta, tb = a['type'], b['type']
    if ta == tb == 'text' and a['y'] == b['y']:
        if b['x'] == a['x'] + len(a['text'])*8:
            return text(a['x'], a['y'], a['text'] + b['text'])
        if a['x'] == b['x'] + len(b['text'])*8:
            return text(b['x'], b['y'], b['text'] + a['text'])
    if ta == tb == 'line' and not a.get('marker') and not b.get('marker'):
        x,y,u,v = a['p']; p,q,r,s = b['p']
        if (u-x)*(s-q) == (v-y)*(r-p) and (p-x)*(v-y) == (q-y)*(u-x) and contacts(a,b):
            pts = sorted([(x,y),(u,v),(p,q),(r,s)], key=lambda p:(p[1],p[0]))
            return line(*pts[0], *pts[-1], a.get('broken') or b.get('broken'))
    if ta == 'circle' and tb == 'line':
        return circle_line(a, b)
    if tb == 'circle' and ta == 'line':
        return circle_line(b, a)
    return None


def circle_line(c, l):
    if l.get('marker') or c['r'] > 4:
        return None
    x,y = c['x'], c['y']
    a,b,d,e = l['p']
    if abs((x-a)*(e-b)-(y-b)*(d-a)) > 1e-6:
        return None
    # Small circle symbols decorate the first line that reaches their cell.
    near = lambda p,q: abs(p-x) <= 8 and abs(q-y) <= 8
    if near(d,e):
        p = (a,b,x,y)
    elif near(a,b):
        p = (d,e,x,y)
    else:
        return None
    m = 'circle' if c.get('filled') else ('open_circle' if c['r'] == 3 else 'big_open_circle')
    return line(*p, broken=l.get('broken'), marker=m)


def merge_all(items):
    result = list(items)
    # Keep the earliest slot whenever two fragments are joined.
    changed = True
    while changed:
        changed = False
        for i in range(len(result)):
            for j in range(i+1, len(result)):
                m = merge(result[i], result[j])
                if m is not None:
                    result[i] = m
                    result.pop(j)
                    changed = True
                    break
            if changed:
                break
    return result


def components(items, adjacent):
    groups = []
    used = set()
    for i in range(len(items)):
        if i in used:
            continue
        found = {i}
        queue = [i]
        used.add(i)
        while queue:
            j = queue.pop()
            for k in range(len(items)):
                if k not in used and adjacent(items[j], items[k]):
                    used.add(k)
                    found.add(k)
                    queue.append(k)
        groups.append([items[k] for k in sorted(found)])
    return groups


def as_rectangle(items):
    if not items or any(e['type'] not in ('line', 'arc') for e in items):
        return None
    segs = [e for e in items if e['type'] == 'line']
    arcs = [e for e in items if e['type'] == 'arc']
    if len(segs) != 4 or len(arcs) not in (0,4):
        return None
    horiz = [e for e in segs if e['p'][1] == e['p'][3]]
    vert = [e for e in segs if e['p'][0] == e['p'][2]]
    if len(horiz) != 2 or len(vert) != 2:
        return None
    h1,h2 = sorted(horiz, key=lambda e:e['p'][1])
    v1,v2 = sorted(vert, key=lambda e:e['p'][0])
    x,y,xx,yy = v1['p'][0],h1['p'][1],v2['p'][0],h2['p'][1]
    rx = arcs[0]['r'] if arcs else 0
    if all(h['p'][0] == x+rx and h['p'][2] == xx-rx for h in horiz) and all(v['p'][1] == y+rx and v['p'][3] == yy-rx for v in vert):
        return rect(x,y,xx-x,yy-y,rx,broken=any(e.get('broken') for e in segs))
    return None
EOF"}

