"""Parse character cells, connect strokes, and assemble diagram elements."""
import re
import unicodedata
from collections import deque
from svg import line, arc, circle, polygon, rect, text, translated, merge_all, components, contacts, as_rectangle
from glyphs import GLYPHS

H = set('-~─–—┄')
V = set('|:│┆┊╎')
SL = set('/╱')
BS = set('\\╲')
TOP = set('.,')
BOT = set("'`")


def fixed(ch):
    a = []
    for shape in GLYPHS.get(ch, []):
        kind, *p = shape
        a.append({'l':line, 'a':arc, 'c':circle, 'p':polygon, 'r':rect}[kind](*p))
    return a


def fixed_port(ch, port):
    xy = {'L':(0,8), 'R':(8,8), 'U':(4,0), 'D':(4,16), 'UL':(0,0), 'UR':(8,0), 'DL':(0,16), 'DR':(8,16)}[port]
    for s in GLYPHS.get(ch, []):
        if s[0] == 'l' and (tuple(s[1:3]) == xy or tuple(s[3:5]) == xy):
            return True
        if s[0] == 'a' and (tuple(s[1:3]) == xy or tuple(s[3:5]) == xy):
            return True
    return False


def strong(ch, port):
    if port in ('L','R') and ch in H: return True
    if port in ('U','D') and ch in V: return True
    if port in ('UR','DL') and ch in SL: return True
    if port in ('UL','DR') and ch in BS: return True
    return fixed_port(ch,port)


def medium(ch, port):
    if strong(ch,port): return True
    if port in ('L','R') and ch in set('+oO*#.,\'`'): return True
    if port == 'U' and ch in set("+*#'`"): return True
    if port == 'D' and ch in set('+*#.,'): return True
    if len(port) == 2 and ch == 'X': return True
    return False

DIRS = [('UL',-1,-1,'DR',(0,0)),('U',0,-1,'D',(4,0)),('UR',1,-1,'DL',(8,0)),
        ('L',-1,0,'R',(0,8)),('R',1,0,'L',(8,8)),
        ('DL',-1,1,'UR',(0,16)),('D',0,1,'U',(4,16)),('DR',1,1,'UL',(8,16))]


def make_cell(grid,x,y):
    ch = grid[(x,y)]
    c = lambda dx,dy: grid.get((x+dx,y+dy),' ')
    left,right,up,down = c(-1,0),c(1,0),c(0,-1),c(0,1)
    result = []
    def L(*p): result.append(line(*p))
    def A(*p): result.append(arc(*p))
    def P(pts): result.append(polygon(pts))
    def near(port,predicate=strong):
        for d,dx,dy,back,point in DIRS:
            if d == port:
                return predicate(c(dx,dy),back)
    if ch in GLYPHS:
        result = fixed(ch)
    elif ch in '-~':
        L(0,8,8,8,ch=='~')
    elif ch == '=':
        L(0,6,8,6); L(0,10,8,10)
    elif ch == '_':
        a,b=0,8
        if left == '|' or c(-1,1) == '|': a=-4
        elif left in SL: a=-8
        if right == '|' or c(1,1) == '|': b=12
        elif right in BS: b=16
        L(a,16,b,16)
    elif ch == '|':
        end=16
        diag=[]
        if c(-1,1) in SL: end=8; diag.append((4,8,0,16))
        if c(1,1) in BS: end=8; diag.append((4,8,8,16))
        L(4,0,4,end)
        for p in diag:L(*p)
        if strong(left,'R'): L(0,8,4,8)
        if strong(right,'L'): L(4,8,8,8)
    elif ch == ':':
        if up in V or down in V:
            L(4,0,4,16,True)
    elif ch in '+X':
        pred=medium if ch=='+' else strong
        for d,dx,dy,back,pt in DIRS:
            if pred(c(dx,dy),back):L(*pt,4,8)
    elif ch in '/\\':
        if ch=='/':
            if down == '|': L(8,0,4,8); L(4,8,4,16)
            else:L(8,0,0,16)
        else:
            if down == '|':L(0,0,4,8); L(4,8,4,16)
            else:L(0,0,8,16)
        if strong(left,'R'):L(0,8,4,8)
        if strong(right,'L'):L(4,8,8,8)
    elif ch in 'oO*':
        ports=[d for d,dx,dy,back,pt in DIRS if strong(c(dx,dy),back)]
        if ports:
            result.append(circle(4,8,3 if ch!='O' else 4,ch=='*'))
        if ch=='*':
            if medium(left,'R'):L(0,8,4,8)
            if medium(right,'L'):L(4,8,8,8)
        if 'D' in ports:L(4,12,4,16)
        if 'DL' in ports:L(0,16,2,12)
        if 'DR' in ports:L(6,12,8,16)
    elif ch=='#':
        if any(medium(c(dx,dy),back) for d,dx,dy,back,pt in DIRS if len(d)==1):
            if medium(up,'D'):L(4,0,4,4)
            result.append(rect(0,4,8,8,filled=True))
            if medium(down,'U'):L(4,12,4,16)
    elif ch in '<>':
        ls,rs=medium(left,'R'),medium(right,'L')
        if ch=='>':
            if ls or (left=='>' and rs):P([(0,4),(8,8),(0,12)])
            if rs:L(0,4,8,8); L(8,8,0,12)
        else:
            if rs or (right=='<' and ls):P([(8,4),(0,8),(8,12)])
            if ls:L(8,4,0,8); L(0,8,8,12)
    elif ch in '^vV':
        us,ds=medium(up,'D'),medium(down,'U')
        if ch=='^':
            if ds:P([(0,12),(4,0),(8,12)]); L(4,12,4,16)
            if us:L(4,0,0,16); L(4,0,8,16)
        else:
            if us:L(4,0,4,4); P([(0,4),(8,4),(4,16)])
            if ds:L(0,0,4,16); L(8,0,4,16)
    elif ch in TOP or ch in BOT:
        bottom=ch in TOP
        dy=1 if bottom else -1
        vchar=down if bottom else up
        vertical=strong(vchar, 'U' if bottom else 'D')
        l,r=medium(left,'R'),medium(right,'L')
        if vertical:
            if bottom:
                if l:A(0,8,4,12,4,1)
                if r:A(8,8,4,12,4,0)
                L(4,12,4,16)
            else:
                L(4,0,4,4)
                if l:A(4,4,0,8,4,1)
                if r:A(4,4,8,8,4,0)
        else:
            if bottom:
                dl = c(-1,1) in SL or c(-1,1)=='('
                dr = c(1,1) in BS or c(1,1)==')'
                if dr:A(0,8,6,12,8,1); L(6,12,8,16)
                if dl:A(8,8,2,12,8,0); L(2,12,0,16)
            else:
                ul = c(-1,-1) in BS or c(-1,-1)=='('
                ur = c(1,-1) in SL or c(1,-1)==')'
                if ul:L(0,0,2,4); A(2,4,8,8,8,0)
                if ur:L(8,0,6,4); A(6,4,0,8,8,1)
    elif ch in '()':
        inward=8 if ch=='(' else 0
        r=16
        if up in TOP or down in BOT: inward=4; r=12
        A(inward,0,inward,16,r,int(ch==')'))
    if not result:
        result=[text(2,12,ch)]
    return [translated(a,8*x,16*y) for a in result]


def grid_components(grid):
    used=set()
    result=[]
    for pos in sorted(grid,key=lambda p:(p[1],p[0])):
        if pos in used:continue
        queue=[pos]; used.add(pos); found=[]
        while queue:
            x,y=queue.pop(); found.append((x,y))
            for dx in (-1,0,1):
                for dy in (-1,0,1):
                    p=x+dx,y+dy
                    if p not in used and p in grid:
                        used.add(p); queue.append(p)
        result.append(sorted(found,key=lambda p:(p[1],p[0])))
    return result


def special_span(grid,span):
    # Compact complete figures are recognized before stroke composition.
    x=min(p[0] for p in span); y=min(p[1] for p in span)
    mx=max(p[0] for p in span); my=max(p[1] for p in span)
    rows=[''.join(grid.get((xx,yy),' ') for xx in range(x,mx+1)).rstrip() for yy in range(y,my+1)]
    if rows == ['()']:
        return [circle(x*8+8,y*16+8,4)]
    if len(rows)==3 and rows[1].startswith('(') and rows[1].endswith(')'):
        a=rows[0]; b=rows[2]
        if a.startswith(' .') and a.endswith('.') and b.startswith(' '+"`") and b.endswith("'") and len(a)==len(rows[1])-1 and len(b)==len(a):
            n=len(rows[1]); return [circle(x*8+n*4,y*16+24,n*4-4)]
    return None


def read_grid(source):
    # Quoted labels do not participate in the drawing grid or its dimensions.
    source=source.split('# Legend:',1)[0]
    grid={}; labels=[]
    for y,row in enumerate(source.split('\n')):
        if row.endswith('\r'):row=row[:-1]
        x=0; i=0
        while i<len(row):
            ch=row[i]
            if ch=='"':
                j=i+1
                while j<len(row):
                    if row[j]=='"' and row[j-1]!='\\':break
                    j+=1
                if j<len(row):
                    labels.append(text(x*8+2,y*16+12,row[i+1:j]))
                    x+=j-i+1; i=j+1; continue
            if not ch.isspace():grid[(x,y)]=ch
            x+=2 if unicodedata.east_asian_width(ch) in ('W','F') else 1
            i+=1
    return grid,labels


def render_diagram(source):
    grid,labels=read_grid(source)
    width=(max((x for x,y in grid),default=0)+2)*8
    height=(max((y for x,y in grid),default=0)+2)*16
    output=[]; groups=[]
    for span in grid_components(grid):
        special=special_span(grid,span)
        if special is not None:
            output.extend(special); continue
        primitives=[]
        for x,y in span:primitives.extend(make_cell(grid,x,y))
        primitives=merge_all(primitives)
        cluster=components(primitives,contacts)
        shapes=[]; singles=[]
        for comp in cluster:
            r=as_rectangle(comp)
            if r is not None:shapes.append(r)
            elif len(comp)==1:
                if comp[0]['type']=='rect':shapes.append(comp[0])
                else:singles.extend(comp)
            else:groups.append({'type':'group','items':comp})
        output.extend(shapes+singles)
    output+=groups+labels
    # A class label belongs to the innermost containing closed figure.
    remove=set()
    for i,t in enumerate(output):
        if t['type']!='text':continue
        match=re.match(r'^\{([^}]+)\}',t['text'])
        if not match:continue
        containers=[]
        for j,s in enumerate(output):
            if s['type']=='rect' and s['x']<t['x']<s['x']+s['w'] and s['y']<t['y']<s['y']+s['h']:
                containers.append((s['w']*s['h'],j))
        if containers:
            _,j=min(containers)
            output[j].setdefault('classes',[]).extend(match.group(1).split(','))
            remove.add(i)
    output=[e for i,e in enumerate(output) if i not in remove]
    return width,height,output
