        ('DL',-1,1,'UR',(0,16)),('D',0,1,'U',(4,16)),('DR',1,1,'UL',(8,16))]


def make_cell(grid,x,y):
    ch = grid[(x,y)]
    c = lambda dx,dy: grid.get((x+dx,y+dy),' ')
    left,right,up,down = c(-1,0),c(1,0),c(0,-1),c(0,1)
    result = []
