    return [translated(a,8*x,16*y) for a in result]


def grid_components(grid):
    used=set()
    result=[]
    for pos in sorted(grid,key=lambda p:(p[1],p[0])):
        if pos in used:continue
        queue=[pos]; used.add(pos); found=[]
        while queue:
            x,y=queue.pop(); found.append((x,y))
            for dx in (-1,0,1):
                for dy in (-1,0,1):
                    p=x+dx,y+dy
                    if p not in used and p in grid:
                        used.add(p); queue.append(p)
        result.append(sorted(found,key=lambda p:(p[1],p[0])))
    return result


def special_span(grid,span):
    # Compact complete figures are recognized before stroke composition.
    x=min(p[0] for p in span); y=min(p[1] for p in span)
    mx=max(p[0] for p in span); my=max(p[1] for p in span)
    rows=[''.join(grid.get((xx,yy),' ') for xx in range(x,mx+1)).rstrip() for yy in range(y,my+1)]
    if rows == ['()']:
        return [circle(x*8+8,y*16+8,4)]
    if len(rows)==3 and rows[1].startswith('(') and rows[1].endswith(')'):
        a=rows[0]; b=rows[2]
        if a.startswith(' .') and a.endswith('.') and b.startswith(' '+"`") and b.endswith("'") and len(a)==len(rows[1])-1 and len(b)==len(a):
            n=len(rows[1]); return [circle(x*8+n*4,y*16+24,n*4-4)]
    return None


def read_grid(source):
    # Quoted labels do not participate in the drawing grid or its dimensions.
    source=source.split('# Legend:',1)[0]
    grid={}; labels=[]
    for y,row in enumerate(source.split('\n')):
        if row.endswith('\r'):row=row[:-1]
        x=0; i=0
        while i<len(row):
            ch=row[i]
            if ch=='"':
                j=i+1
                while j<len(row):
                    if row[j]=='"' and row[j-1]!='\\':break
                    j+=1
                if j<len(row):
                    labels.append(text(x*8+2,y*16+12,row[i+1:j]))
                    x+=j-i+1; i=j+1; continue
            if not ch.isspace():grid[(x,y)]=ch
            x+=2 if unicodedata.east_asian_width(ch) in ('W','F') else 1
            i+=1
    return grid,labels


def render_diagram(source):
    grid,labels=read_grid(source)
    width=(max((x for x,y in grid),default=0)+2)*8
    height=(max((y for x,y in grid),default=0)+2)*16
    output=[]; groups=[]
    for span in grid_components(grid):
        special=special_span(grid,span)
        if special is not None:
            output.extend(special); continue
        primitives=[]
        for x,y in span:primitives.extend(make_cell(grid,x,y))
        primitives=merge_all(primitives)
        cluster=components(primitives,contacts)
        shapes=[]; singles=[]
        for comp in cluster:
            r=as_rectangle(comp)
            if r is not None:shapes.append(r)
            elif len(comp)==1:
                if comp[0]['type']=='rect':shapes.append(comp[0])
                else:singles.extend(comp)
            else:groups.append({'type':'group','items':comp})
        output.extend(shapes+singles)
    output+=groups+labels
    # A class label belongs to the innermost containing closed figure.
    remove=set()
    for i,t in enumerate(output):
        if t['type']!='text':continue
        match=re.match(r'^\{([^}]+)\}',t['text'])
        if not match:continue
        containers=[]
        for j,s in enumerate(output):
            if s['type']=='rect' and s['x']<t['x']<s['x']+s['w'] and s['y']<t['y']<s['y']+s['h']:
                containers.append((s['w']*s['h'],j))
        if containers:
            _,j=min(containers)
            output[j].setdefault('classes',[]).extend(match.group(1).split(','))
            remove.add(i)
    output=[e for i,e in enumerate(output) if i not in remove]
    return width,height,output
